css:
/* Полоса прогресса чтения. Цвет — токен primary вашей темы (контраст с фоном от 3:1). */
.spb {
  position: fixed;
  left: 0;
  right: 0;
  top: var(--spb-top, env(safe-area-inset-top, 0px)); /* под липкой шапкой: --spb-top = её высота */
  height: 3px;
  z-index: 60;
  pointer-events: none;
  background: var(--spb-track, transparent);
}
.spb__fill {
  height: 100%;
  background: var(--spb-color, var(--primary, #2563eb));
  transform-origin: 0 50%;
  transform: scaleX(0); /* без JS и без поддержки полоса пустая и невидимая */
  will-change: transform;
}
/* Современные браузеры: полосу ведёт сама прокрутка, без единой строки JS */
@supports (animation-timeline: scroll()) {
  .spb__fill {
    animation: spb-grow 1ms linear both;
    animation-timeline: scroll(root block);
  }
}
/* Ведёт JS (запасной путь или режим «до формы»): CSS-анимацию снимаем, иначе она перекроет JS */
.spb--js .spb__fill {
  animation: none;
}
@keyframes spb-grow {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}
/* Уровень 3 (оставить): полоса движется только вместе с прокруткой человека, 1:1.
   Снимаем всё, что даёт собственное движение, — сглаживание, если его добавит дизайн. */
@media (prefers-reduced-motion: reduce) {
  .spb__fill {
    transition: none;
  }
}
/* Контрастная тема Windows: иначе заливку подменит фон и полоса исчезнет */
@media (forced-colors: active) {
  .spb__fill {
    forced-color-adjust: none;
    background: Highlight;
  }
}
@media print {
  .spb {
    display: none;
  }
}

