// Полоса прогресса: JS нужен только старым браузерам и режиму «до формы» (data-until).
// Подключать в конце <body> или с defer: иначе .spb ещё нет в документе.
(() => {
  const bar = document.querySelector('.spb');
  const fill = bar && bar.querySelector('.spb__fill');
  if (!fill) return;
  let target = null;
  try { target = bar.dataset.until ? document.querySelector(bar.dataset.until) : null; } catch (e) { target = null; } // кривой селектор = вся страница
  const native = !target && window.CSS && CSS.supports('animation-timeline: scroll()');
  if (native) return; // всё делает CSS
  bar.classList.add('spb--js');
  const root = document.documentElement;
  let end = 1;
  let dirty = true;
  let queued = false;
  // Один кадр — один проход: раскладку читаем только после смены размеров, не на каждой прокрутке
  const frame = () => {
    queued = false;
    if (dirty) {
      dirty = false;
      end = target
        ? target.getBoundingClientRect().top + window.scrollY - window.innerHeight / 2
        : root.scrollHeight - window.innerHeight;
      end = Math.max(end, 1);
    }
    const p = Math.min(Math.max(window.scrollY / end, 0), 1);
    fill.style.transform = 'scaleX(' + p.toFixed(4) + ')';
  };
  const schedule = (resized) => {
    if (resized) dirty = true;
    if (queued) return;
    queued = true;
    requestAnimationFrame(frame);
  };
  window.addEventListener('scroll', () => schedule(false), { passive: true });
  window.addEventListener('resize', () => schedule(true));
  if ('ResizeObserver' in window) new ResizeObserver(() => schedule(true)).observe(document.body);
  schedule(true);
})();

