// Только если GSAP уже есть на странице: ставить из npm (npm i gsap), не с CDN; баннер лицензии при сборке сохранять.
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);
document.querySelector('.spb').classList.add('spb--js'); // снять CSS-анимацию, иначе она перекроет GSAP
gsap.fromTo('.spb__fill', { scaleX: 0 }, {
  scaleX: 1,
  ease: 'none', // в scrub только без кривой, иначе полоса спорит с прокруткой
  scrollTrigger: { start: 0, end: 'max', scrub: true } // scrub: true, а не число: число даёт отставание
});
// Режим «до формы»: scrollTrigger: { start: 0, endTrigger: '#lead', end: 'top center', scrub: true }
// JS-файл рецепта при этом не подключать.
